import React, { useEffect, useState } from "react";

export default function AdminDashboard() {
  const [users, setUsers] = useState([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  // Update this URL if your backend is deployed differently
  const API_BASE_URL = "http://localhost:5000";

  const fetchUsers = async () => {
    setLoading(true);
    setError("");
    try {
      const res = await fetch(`${API_BASE_URL}/users`);
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to fetch users. Status: ${res.status}, ${text}`);
      }
      const data = await res.json();
      setUsers(data);
    } catch (err) {
      setError(`Error fetching users: ${err.message}`);
    }
    setLoading(false);
  };

  React.useEffect(() => {
    fetchUsers();
  }, []);

  const handleDelete = async (uid) => {
    setError("");
    try {
      const res = await fetch(`${API_BASE_URL}/users/${uid}`, {
        method: "DELETE",
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Failed to delete user. Status: ${res.status}, ${text}`);
      }
      fetchUsers();
    } catch (err) {
      setError(`Error deleting user: ${err.message}`);
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Admin User Management</h2>
      {error && <p style={{ color: "red", whiteSpace: "pre-wrap" }}>{error}</p>}
      {loading ? (
        <p>Loading users...</p>
      ) : (
        <table border="1" cellPadding="10" style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              <th>UID</th>
              <th>Email</th>
              <th>Display Name</th>
              <th>Disabled</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {users.length === 0 ? (
              <tr><td colSpan="5" style={{ textAlign: "center" }}>No users found</td></tr>
            ) : (
              users.map((user) => (
                <tr key={user.uid}>
                  <td>{user.uid}</td>
                  <td>{user.email}</td>
                  <td>{user.displayName || "-"}</td>
                  <td>{user.disabled ? "Yes" : "No"}</td>
                  <td>
                    <button onClick={() => handleDelete(user.uid)} style={{ color: "red" }}>
                      Delete
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      )}
    </div>
  );
}
